<template><view class="page"><app-nav title="我的卡片" fallback-url="/pages/me/me"/><scroll-view class="content" scroll-y><view v-if="loading" class="empty"><text>正在加载...</text></view><view v-else-if="!cards.length" class="empty"><text class="empty-title">还没有抽到卡片</text><view class="go-draw" @tap="goDraw">去抽卡</view></view><view v-else class="card-grid"><view v-for="item in cards" :key="item.drawId" class="history-card" @tap="preview(item)"><image class="history-image" :src="resolveImageUrl(item.finalImageUrl)" mode="aspectFill"></image><view class="history-copy"><text class="history-title">{{ item.cardTitle }}</text><text class="history-time">{{ item.drawTime }}</text></view></view></view></scroll-view></view></template>
<script>import { cardApi,resolveImageUrl } from '@/utils/apiconfig.js';import { getToken } from '@/utils/auth.js';import { requestPromise,isSuccessResponse } from '@/utils/request-helper.js';export default{data(){return{loading:true,cards:[]}},onLoad(){this.load()},onPullDownRefresh(){this.load().finally(()=>uni.stopPullDownRefresh())},methods:{resolveImageUrl,async load(){this.loading=true;const token=getToken();try{const res=await requestPromise({url:cardApi.my,method:'GET',header:{Authorization:`Bearer ${token}`,'X-Wx-Token':token}});this.cards=isSuccessResponse(res)&&Array.isArray(res.data.data)?res.data.data:[]}catch(e){this.cards=[]}finally{this.loading=false}},preview(item){uni.previewImage({current:resolveImageUrl(item.finalImageUrl),urls:[resolveImageUrl(item.finalImageUrl)]})},goDraw(){uni.navigateTo({url:'/pages/card/draw'})}}}</script>
<style lang="scss" scoped>@import '@/styles/design-tokens.scss';.page{@include page-shell;min-height:100vh}.content{flex:1;min-height:0}.card-grid{padding:16rpx $space-page 50rpx;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20rpx}.history-card{background:#fff;border:2rpx solid $border-subtle;box-shadow:$shadow-card;overflow:hidden}.history-image{width:100%;aspect-ratio:3/4;display:block}.history-copy{padding:18rpx}.history-title,.history-time{display:block;font-family:$font-family}.history-title{font-size:26rpx;font-weight:700;color:$text-primary}.history-time{margin-top:7rpx;font-size:20rpx;color:$text-tertiary}.empty{min-height:680rpx;display:flex;flex-direction:column;align-items:center;justify-content:center;font-family:$font-family;color:$text-secondary}.empty-title{font-size:30rpx;font-weight:700}.go-draw{margin-top:24rpx;padding:20rpx 54rpx;background:$accent-primary;color:#fff;border-radius:8rpx;font-size:26rpx}</style>
